input.command:
$maxWait = 10; $waited = 0
while ($waited -lt $maxWait) {
  Start-Sleep -Seconds 1
  $waited++
  try {
    $r = Invoke-RestMethod http://127.0.0.1:4188/api/boards -ErrorAction Stop
    Write-Host "Server ready after ${waited}s"
    break
  } catch {
    Write-Host "Waiting... ${waited}s"
  }
}
